import{_ as o,W as l,s as p,u,I as n,ah as d,w as i,Z as a,A as e}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const V=JSON.parse('{"title":"在 Linux 中如何从命令行查找 VirtualBox 版本 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中如何从命令行查找 VirtualBox 版本 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中如何从命令行查找 VirtualBox 版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中如何从命令行查找 VirtualBox 版本 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190710 How To Find Virtualbox Version From Commandline In Linux","title":"在 Linux 中如何从命令行查找 VirtualBox 版本","tag":"201907"},"relativePath":"201907/20190710 How To Find Virtualbox Version From Commandline In Linux.md","filePath":"[post].md"}'),r={name:"201907/20190710 How To Find Virtualbox Version From Commandline In Linux.md"};function x(b,t,h,g,m,v){const s=l("Link");return u(),p("div",null,[t[23]||(t[23]=n("h1",{id:"在-linux-中如何从命令行查找-virtualbox-版本",tabindex:"-1"},[i("在 Linux 中如何从命令行查找 VirtualBox 版本 "),n("a",{class:"header-anchor",href:"#在-linux-中如何从命令行查找-virtualbox-版本","aria-label":"Permalink to 在 Linux 中如何从命令行查找 VirtualBox 版本"},"​")],-1)),t[24]||(t[24]=n("p",null,[n("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/07/Find-Virtualbox-Version-1-720x340.png",alt:"FInd Virtualbox version from commandline In Linux"})],-1)),n("p",null,[t[3]||(t[3]=i("我使用 Oracle VirtualBox 和 ")),a(s,{href:"https://www.ostechnix.com/setup-headless-virtualization-server-using-kvm-ubuntu/"},{default:e(()=>t[0]||(t[0]=[i("KVM")])),_:1}),t[4]||(t[4]=i(" 虚拟化程序")),a(s,{href:"https://www.ostechnix.com/test-100-linux-and-unix-operating-systems-online-for-free/"},{default:e(()=>t[1]||(t[1]=[i("测试不同的 Linux 操作系统")])),_:1}),t[5]||(t[5]=i("。虽然我偶尔使用 KVM，但 Virtualbox 始终是我的首选。不是因为我不喜欢 KVM，而是因为我只是习惯了 VirtualBox。当在我的 Ubuntu 无头服务器上使用 ")),a(s,{href:"https://www.ostechnix.com/install-oracle-virtualbox-ubuntu-16-04-headless-server/"},{default:e(()=>t[2]||(t[2]=[i("Virtualbox")])),_:1}),t[6]||(t[6]=i(" 时，我需要知道 VirtualBox 的版本。如果它有 GUI，我可以进入 Virtualbox -> About -> Help 轻松找到它。但我的是没有 GUI 的 Ubuntu 服务器。如果你想知道如何在 Linux 中从命令行查找 VirtualBox 版本，可以采用以下几种方法。"))]),t[25]||(t[25]=d(`<h3 id="在-linux-中从命令行查找-virtualbox-版本" tabindex="-1">在 Linux 中从命令行查找 VirtualBox 版本 <a class="header-anchor" href="#在-linux-中从命令行查找-virtualbox-版本" aria-label="Permalink to 在 Linux 中从命令行查找 VirtualBox 版本">​</a></h3><p>要查找已安装的 VirtualBox 的版本，请打开终端并运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vboxmanage --version</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5.2.18_Ubuntur123745</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Find-Virtualbox-Version.png" alt=""></p><p><em>在 Linux 中从命令行查找 Virtualbox 版本</em></p><p>正如你在上面的输出中看到的，安装的 VirtualBox 的版本是 5.2。</p><p>查找 VirtualBox 版本的另一种方法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vbox-img --version</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5.2.18_Ubuntur123745</span></span></code></pre></div><p>或者，你可以使用 <code>head</code> 和 <code>awk</code> 命令来查找 VirtualBox 版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ virtualbox --help | head -n 1 | awk &#39;{print $NF}&#39;</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5.2.18_Ubuntu</span></span></code></pre></div><p>或者，使用 <code>echo</code> 命令结合 <code>head</code> 和 <code>awk</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo $(virtualbox --help | head -n 1 | awk &#39;{print $NF}&#39;)</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5.2.18_Ubuntu</span></span></code></pre></div><p>以上命令适用于任何 Linux 发行版。如果你使用的是 Ubuntu，你可以使用 <code>dpkg</code> 命令查看 VirtualBox 版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ dpkg -l | grep virtualbox | awk &#39;{print $3}&#39;</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5.2.30-130521~Ubuntu~bionic</span></span>
<span class="line"><span>5.2.18-dfsg-2~ubuntu18.04.5</span></span></code></pre></div><p>就是这些了。这些是从 Linux 中的终端查找 Oracle Virtualbox 版本的几种方法。希望这篇文章很有用。</p><p>参考来自：</p>`,26)),n("ul",null,[n("li",null,[a(s,{href:"https://askubuntu.com/questions/420363/how-do-i-check-virtualbox-version-from-cli"},{default:e(()=>t[7]||(t[7]=[i("AskUbuntu")])),_:1})])]),t[26]||(t[26]=n("hr",null,null,-1)),n("p",null,[t[9]||(t[9]=i("via: ")),a(s,{href:"https://www.ostechnix.com/how-to-find-virtualbox-version-from-commandline-in-linux/"},{default:e(()=>t[8]||(t[8]=[i("https://www.ostechnix.com/how-to-find-virtualbox-version-from-commandline-in-linux/")])),_:1})]),n("p",null,[t[14]||(t[14]=i("作者：")),a(s,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>t[10]||(t[10]=[i("sk")])),_:1}),t[15]||(t[15]=i(" 选题：")),a(s,{href:"https://github.com/lujun9972"},{default:e(()=>t[11]||(t[11]=[i("lujun9972")])),_:1}),t[16]||(t[16]=i(" 译者：")),a(s,{href:"https://github.com/geekpi"},{default:e(()=>t[12]||(t[12]=[i("geekpi")])),_:1}),t[17]||(t[17]=i(" 校对：")),a(s,{href:"https://github.com/wxy"},{default:e(()=>t[13]||(t[13]=[i("wxy")])),_:1})]),n("p",null,[t[20]||(t[20]=i("本文由 ")),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>t[18]||(t[18]=[i("LCTT")])),_:1}),t[21]||(t[21]=i(" 原创编译，")),a(s,{href:"https://linux.cn/"},{default:e(()=>t[19]||(t[19]=[i("Linux中国")])),_:1}),t[22]||(t[22]=i(" 荣誉推出"))])])}const f=o(r,[["render",x]]);export{V as __pageData,f as default};
